from taf.transport.ssh import ssh


class AddKeyToKnownHost(object):
    def __init__(self):
        self.shell = None
        self.msm_ip = "192.168.255.1"
        self.esm_ip = "192.168.255.7"
        self.username = "toor4nsn"
        self.password = "oZPS0POrRieRtu"
        self.shell = ssh()

    def login_to_msm(self):
        self.shell.connect_to(hostname=self.msm_ip, username=self.username, password=self.password)

    def login_to_esm(self):
        proxy = self.shell.connect_to(hostname=self.msm_ip, username=self.username, password=self.password)
        self.shell.connect_to(hostname=self.esm_ip, username=self.username, password=self.password, proxy=proxy)

    def add_key(self, radio_ip, num=None):
        self.shell.send_command(
            "lxc-attach -n 0x{num}018  ssh-keyscan {ip} >> /user/toor4nsn/.ssh/known_hosts".format(ip=radio_ip, num=num), get_pty=True)
        self.shell.read_output()

    def close_connection(self):
        self.shell.disconnect()
